import './swag-assistant-trace-list.scss';
import { collectExportIds, exportFileName, exportRequest, saveBlob } from '../../export';
import { conversationPreview } from './preview';
import { humanMs } from '../swag-assistant-trace-detail/facts';
import template from './swag-assistant-trace-list.html.twig';

const { Criteria } = Shopware.Data;

/**
 * `AssistantTraceExportController::MAX_CONVERSATIONS`, mirrored so the client asks for what the
 * server will accept rather than being refused after the round trip. **The two must stay equal.**
 *
 * This is the bound on the *export*, not on one API request. Collecting this many ids takes several
 * `search-ids` pages — see {@see SEARCH_IDS_PAGE_LIMIT}, which is what asking for all of them in
 * one request used to run into.
 */
const EXPORT_LIMIT = 1000;

Shopware.Component.register('swag-assistant-trace-list', {
    template,

    inject: ['repositoryFactory'],

    data() {
        return {
            conversations: null,
            channelNames: {},
            isLoading: true,
            sortBy: 'createdAt',
            sortDirection: 'DESC',
            outcomeFilter: null,
            total: 0,
            selectionCount: 0,
            exportError: null,
        };
    },

    computed: {
        repository() {
            return this.repositoryFactory.create('swag_assistant_conversation');
        },

        columns() {
            return [
                {
                    property: 'createdAt',
                    label: 'swag-assistant-trace.list.columnCreatedAt',
                    primary: true,
                    allowResize: true,
                },
                { property: 'salesChannelId', label: 'swag-assistant-trace.list.columnSalesChannel' },
                { property: 'customer.lastName', label: 'swag-assistant-trace.list.columnUser' },
                { property: 'turnCount', label: 'swag-assistant-trace.list.columnTurnCount' },
                // The column that makes this a triage tool rather than a log reader: with the
                // filter below, `tool_limit_exceeded` and `escalate` are reachable without reading
                // every row. Those are the two live failure modes.
                { property: 'outcome', label: 'swag-assistant-trace.list.columnOutcome' },
                // What the conversation was actually about, which the grid never used to say. The
                // three columns above describe how a turn went; without these, finding the one
                // `tool_limit_exceeded` row that matters means opening every one of them.
                //
                // Not sortable, and deliberately: they are derived from a JSON column, so the DAL
                // has nothing to sort on and a header that looked clickable would do nothing.
                {
                    property: 'question',
                    label: 'swag-assistant-trace.list.columnQuestion',
                    allowResize: true,
                    sortable: false,
                    width: '260px',
                },
                {
                    property: 'reply',
                    label: 'swag-assistant-trace.list.columnReply',
                    allowResize: true,
                    sortable: false,
                    width: '260px',
                },
                { property: 'totalMs', label: 'swag-assistant-trace.list.columnTotalMs' },
            ];
        },

        /**
         * How many conversations the buttons would export right now.
         *
         * The selection when there is one, otherwise everything the filter matches. This is the one
         * place that rule lives — the label reads it, the disabled state reads it, and the handler
         * branches on the same thing, so the button cannot promise one count and send another.
         */
        exportCount() {
            // Clamped, because the label must not promise rows the export will not contain. It read
            // `|| this.total` until 2026-09-02, so a shop with 1750 conversations offered to export
            // all 1750 and delivered the newest 1000 — the button promising one count and sending
            // another, which is the exact thing this computed exists to prevent.
            return this.selectionCount || Math.min(this.total, EXPORT_LIMIT);
        },

        /**
         * What the buttons would export, said in words beside them rather than inside them.
         *
         * `$t`, not `$tc`: there is no plural form here, and `$tc`'s second argument is the
         * pluralization choice — passing named values through it dropped them silently, which is
         * how the button once read "Export all 175 as" with nothing after the "as".
         */
        exportScope() {
            // Three states, and the third is not decoration: a filter matching more than the export
            // bound is the one case where "all" would be a lie, so it says which ones instead.
            if (!this.selectionCount && this.total > EXPORT_LIMIT) {
                return this.$t('swag-assistant-trace.list.scopeCapped', {
                    count: this.exportCount,
                    total: this.total,
                });
            }

            const key = this.selectionCount
                ? 'swag-assistant-trace.list.scopeSelected'
                : 'swag-assistant-trace.list.scopeAll';

            return this.$t(key, { count: this.exportCount });
        },

        /**
         * Every outcome `TurnOutcomeResolver` can actually produce, and nothing else.
         *
         * **Two of the four previous entries matched nothing.** It offered `escalate` where the
         * resolver emits `escalated`, and `refused`, which the resolver has never produced — so
         * filtering by either returned an empty list that read as "no such conversations" rather than
         * "no such value". Found on 2026-08-26 while adding `shop_info_answered`; a filter that
         * silently matches nothing is the same defect class as an empty blocklist reporting itself as
         * configured (D5).
         *
         * Labels are the raw values on purpose: they are what the column shows and what an export
         * contains, so translating them here would leave a merchant filtering by one word and reading
         * another.
         */
        outcomeOptions() {
            return [
                'product_shown',
                'shop_info_retrieved',
                'orders_shown',
                'cart_added',
                // Missing since it was introduced, and found while adding `orders_shown` above: a
                // merchant could filter for every outcome the resolver produces except this one.
                'checkout_offered',
                'escalated',
                'no_result',
                'tool_limit_exceeded',
                'error',
            ].map((value) => ({ value, label: value }));
        },
    },

    created() {
        this.loadChannelNames();
        this.load();
    },

    methods: {
        /**
         * Resolved client-side rather than through an association: `sales_channel_id` is a plain
         * VARCHAR(32) of hex, not a BINARY(16) foreign key, so the DAL cannot join it. Showing a
         * raw uuid to a merchant is not an option, and changing the column type is a migration
         * this page does not justify.
         */
        async loadChannelNames() {
            const channels = await this.repositoryFactory
                .create('sales_channel')
                .search(new Criteria(1, 100), Shopware.Context.api);

            this.channelNames = Object.fromEntries(channels.map((channel) => [channel.id, channel.name]));
        },

        channelName(id) {
            return this.channelNames[id] ?? id;
        },

        /**
         * Two states, and the second is not a fallback. A conversation with no customer either never
         * had one or had one who deleted their account — `ON DELETE SET NULL` makes those
         * indistinguishable on purpose, so "Guest user" is the only thing true in both cases.
         */
        userName(conversation) {
            const customer = conversation.customer;

            if (!customer) {
                return this.$tc('swag-assistant-trace.list.guestUser');
            }

            return `${customer.firstName ?? ''} ${customer.lastName ?? ''}`.trim();
        },

        async load() {
            this.isLoading = true;

            const criteria = new Criteria(1, 25);
            criteria.addSorting(Criteria.sort(this.sortBy, this.sortDirection));
            // The name comes off the association rather than a second lookup: `customer_id` is a
            // real foreign key, unlike `sales_channel_id`.
            criteria.addAssociation('customer');

            if (this.outcomeFilter) {
                criteria.addFilter(Criteria.equals('outcome', this.outcomeFilter));
            }

            this.conversations = await this.repository.search(criteria, Shopware.Context.api);
            // `Criteria`'s default total-count-mode is already 1, which counts exactly. There was a
            // `setTotalCountMode(Criteria.TOTAL_COUNT_MODE_EXACT)` here for one afternoon: that
            // constant does not exist on the admin's Criteria, so it set `undefined` and replaced a
            // working default with none — the export then offered "all 25", the page size, for a
            // list of 115. Measured in the running Administration, not assumed.
            this.total = this.conversations.total ?? 0;
            this.isLoading = false;
        },

        /** `8183` reads as an id. A duration column has to read as a duration. */
        duration(ms) {
            return ms ? humanMs(ms) : '—';
        },

        /**
         * The last exchange of a conversation, for the two prose columns.
         *
         * Read straight off the row: `transcript` is ApiAware and the criteria below restricts no
         * fields, so the grid already holds every conversation's transcript whether these columns
         * render it or not. There is no second request here and nothing to add to the criteria.
         */
        preview(conversation) {
            return conversationPreview(conversation.transcript);
        },

        onOutcomeFilterChange(value) {
            this.outcomeFilter = value;
            this.load();
        },

        onSelectionChange(selection) {
            this.selectionCount = Object.keys(selection ?? {}).length;
        },

        /**
         * **Every rejection below has to land in `exportError`.**
         *
         * Neither branch used to be awaited, so anything that threw on the way to the file became
         * an unhandled promise rejection in the console and nothing at all in the page. That is how
         * a permanently broken "Export all" — the id search was refused with a 400 on every shop,
         * every time — survived to a release: the feature failed exactly as loudly as a feature
         * that works.
         */
        async onExport() {
            this.exportError = null;

            try {
                await (this.selectionCount
                    ? this.download(Object.keys(this.$refs.grid?.selection ?? {}))
                    : this.exportFiltered());
            } catch (error) {
                // The API's own sentence when there is one. A DAL refusal arrives as an axios error
                // whose `message` is "Request failed with status code 400", which tells a merchant
                // nothing; the `detail` underneath it says what was actually wrong.
                this.exportError = error?.response?.data?.errors?.[0]?.detail
                    ?? this.$tc('swag-assistant-trace.list.exportFailed');
            }
        },

        /**
         * Every row the current filter matches, not just the page.
         *
         * Shopware's own select-all covers the current page, so a literal reading of "select all"
         * would quietly export 25 rows. `searchIds` fetches ids only, which is cheap even at the
         * bound the server enforces — but it may not fetch more than `shopware.api.max_limit` of
         * them per request, which is why the ids arrive a page at a time.
         */
        async exportFiltered() {
            const ids = await collectExportIds(
                (page, limit) => this.repository.searchIds(this.exportCriteria(page, limit), Shopware.Context.api),
                EXPORT_LIMIT,
            );

            await this.download(ids);
        },

        /**
         * One page of the filtered id search.
         *
         * The `id` tiebreak is what makes paging safe. `createdAt` alone is not a total order —
         * traces written in the same millisecond have no defined order between them, so a
         * conversation on a page boundary could be returned twice or skipped entirely, and the
         * skipped one is the failure nobody would notice.
         */
        exportCriteria(page, limit) {
            const criteria = new Criteria(page, limit);
            criteria.addSorting(Criteria.sort(this.sortBy, this.sortDirection));
            criteria.addSorting(Criteria.sort('id', 'ASC'));

            if (this.outcomeFilter) {
                criteria.addFilter(Criteria.equals('outcome', this.outcomeFilter));
            }

            return criteria;
        },

        /**
         * The download goes through an authenticated request rather than `window.open`: the route
         * emits customer names and is ACL-protected, so it cannot be opened as a plain URL.
         */
        async download(ids) {
            const { url, options } = exportRequest(Shopware.Context.api, ids);
            const response = await fetch(url, options);

            if (!response.ok) {
                const problem = await response.json().catch(() => ({}));

                // Shown in the page rather than through a notification mixin: nothing in this module
                // uses one, and the endpoint's refusals are instructions about the filter — "narrow
                // it and try again" — which belong beside the filter they are about.
                this.exportError = problem.error ?? this.$tc('swag-assistant-trace.list.exportFailed');

                return;
            }

            saveBlob(await response.blob(), exportFileName());
        },
    },
});
